Below is a **complete, self‑contained** Go program that starts an HTTP server on port 8080 and replies with the text **“Hello, World!”** to **every** incoming request (any path, any method).

```go
// hello_server.go
package main

import (
	"fmt"
	"log"
	"net/http"
)

// helloHandler writes the static response for every request.
func helloHandler(w http.ResponseWriter, r *http.Request) {
	// You can set a content‑type header if you like:
	w.Header().Set("Content-Type", "text/plain; charset=utf-8")

	// Write the response body.
	_, err := fmt.Fprintln(w, "Hello, World!")
	if err != nil {
		// If writing fails, log the error – the client will already have
		// received a partial response.
		log.Printf("error writing response: %v", err)
	}
}

func main() {
	// Register the handler for *all* routes.
	http.HandleFunc("/", helloHandler)

	// Choose the address/port to listen on.
	addr := ":8080"
	fmt.Printf("Starting server on http://localhost%s …\n", addr)

	// ListenAndServe blocks until the server stops or an error occurs.
	if err := http.ListenAndServe(addr, nil); err != nil {
		log.Fatalf("server failed: %v", err)
	}
}
```

